// 16x16 reverse-DNS heatmap for one /24 (256 addresses, last octet 0 top-left, 255 bottom-right).
//   green = PTR that forward-confirms (FCrDNS)   amber = PTR whose name does not resolve back to the IP
//   grey = no PTR                                hatched = looks auto-generated by the provider (e.g. 160-22-108-5.isp.net)
// Cells are real buttons with one tab stop (arrow keys move inside the grid). A searchable list repeats the data.
import { h, plural, srOnly, pill } from '../ui/dom.js';
import { dataTable } from '../ui/table.js';

const PAGE = 40;
const kind = (r) => (!r.ptr ? 'none' : r.fcrdns === true ? 'ok' : 'warn');
const WORD = { ok: 'PTR present and forward-confirmed', warn: 'PTR present but not forward-confirmed', none: 'no PTR record' };
const WORD_FC = (r) => (r.fcrdns === true ? 'forward-confirmed' : r.fcrdns === false ? 'the name does not resolve back to this IP' : 'forward check not available');
const octet = (r, i) => { const m = /(\d+)$/.exec(r.ip || ''); return /^\d+\.\d+\.\d+\.\d+$/.test(r.ip || '') && m ? Number(m[1]) : i; };

/** ptrGrid({ rows, stats, base }) -> element */
export function ptrGrid({ rows = [], stats = {}, base = '' } = {}) {
  const cells = Array.from({ length: 256 }, () => null);
  rows.forEach((r, i) => { const o = octet(r, i); if (o >= 0 && o < 256) cells[o] = r; });
  const known = cells.filter(Boolean).length;
  const state = { hideAuto: false, q: '', shown: PAGE, focus: 0 };

  const tip = h('p', { class: 'text-sm min-h-[2.75rem] mt-2 mono break-all', 'aria-live': 'polite' }, 'Hover or focus a square to see the address and its PTR name.');
  const btns = cells.map((r, o) => {
    const k = r ? kind(r) : 'none';
    const desc = r ? `${r.ip}: ${r.ptr ? `${r.ptr}, ${WORD_FC(r)}` : WORD.none}${r.auto ? ', looks auto-generated' : ''}` : `.${o}: not scanned`;
    const b = h('button', { type: 'button', class: `ptr-cell ptr-${k}${r && r.auto ? ' ptr-auto' : ''}`, 'aria-label': desc, title: desc, tabindex: o === 0 ? '0' : '-1', 'data-o': String(o) });
    const show = () => { tip.textContent = desc; };
    b.addEventListener('mouseenter', show); b.addEventListener('focus', () => { show(); state.focus = o; });
    b.addEventListener('click', () => { search.value = r ? r.ip : ''; state.q = search.value.toLowerCase(); state.shown = PAGE; drawList(); });
    return b;
  });
  const grid = h('div', { class: 'ptr-grid', role: 'group', 'aria-label': `Reverse DNS heatmap for ${base || 'the /24'}: 256 addresses` }, btns);
  grid.addEventListener('keydown', (e) => {
    const step = { ArrowRight: 1, ArrowLeft: -1, ArrowDown: 16, ArrowUp: -16 }[e.key];
    let to = null;
    if (step != null) to = state.focus + step; else if (e.key === 'Home') to = e.ctrlKey ? 0 : state.focus - (state.focus % 16); else if (e.key === 'End') to = e.ctrlKey ? 255 : state.focus - (state.focus % 16) + 15;
    if (to == null || to < 0 || to > 255) return;
    e.preventDefault();
    btns[state.focus].tabIndex = -1; btns[to].tabIndex = 0; btns[to].focus();
  });

  const legendKey = (cls, text) => h('li', { class: 'inline-flex items-center' }, h('span', { class: `ptr-key ${cls}`, 'aria-hidden': 'true' }), text);
  const count = h('span', { class: 'text-xs text-mute', role: 'status', 'aria-live': 'polite' });
  const hideAuto = h('input', { type: 'checkbox', id: 'ptr-hide-' + Math.random().toString(36).slice(2, 7) });
  const autoN = cells.filter((r) => r && r.auto).length;

  function drawGrid() {
    let ok = 0, warn = 0, none = 0, gone = 0;
    cells.forEach((r, o) => {
      const hidden = state.hideAuto && r && r.auto;
      btns[o].classList.toggle('ptr-gone', !!hidden);
      const k = r ? kind(r) : 'none';
      if (hidden) gone += 1; else if (k === 'ok') ok += 1; else if (k === 'warn') warn += 1; else none += 1;
    });
    count.textContent = `${ok} confirmed, ${warn} PTR only, ${none} none${gone ? `, ${gone} auto-generated hidden` : ''}`;
  }
  hideAuto.addEventListener('change', () => { state.hideAuto = hideAuto.checked; drawGrid(); state.shown = PAGE; drawList(); });

  // Searchable list
  const search = h('input', { type: 'search', class: 'mono', placeholder: 'Search by IP or PTR name', 'aria-label': 'Search the PTR records by IP address or name', autocomplete: 'off', spellcheck: 'false' });
  const body = h('div'), more = h('button', { type: 'button', class: 'btn btn-ghost btn-sm' }), note = h('p', { class: 'text-sm text-mute', role: 'status', 'aria-live': 'polite' });
  function drawList() {
    const q = state.q.trim();
    const all = cells.filter((r) => r && r.ptr && !(state.hideAuto && r.auto));
    const match = q ? all.filter((r) => `${r.ip} ${r.ptr}`.toLowerCase().includes(q)) : all;
    const vis = match.slice(0, state.shown);
    body.replaceChildren(vis.length
      ? dataTable(['IP address', 'PTR name', 'Forward-confirmed', 'Type'], vis.map((r) => [r.ip, r.ptr, r.fcrdns === true ? pill('ok', 'Yes') : r.fcrdns === false ? pill('warn', 'No') : pill('mute', 'Unknown'), r.auto ? 'Auto-generated' : 'Custom']), { mono: [0, 1] })
      : h('p', { class: 'text-sm text-mute' }, q ? 'No PTR record matches this search.' : 'No PTR records were found in this block.'));
    note.textContent = `Showing ${vis.length} of ${plural(match.length, 'PTR record')}`;
    const left = match.length - vis.length;
    more.style.display = left > 0 ? '' : 'none';
    more.textContent = `Show ${Math.min(PAGE, left)} more`;
  }
  search.addEventListener('input', () => { state.q = search.value.toLowerCase(); state.shown = PAGE; drawList(); });
  more.addEventListener('click', () => { state.shown += PAGE; drawList(); });

  const s = stats || {};
  const text = `Of ${known || 256} addresses scanned, ${s.with_ptr ?? cells.filter((r) => r && r.ptr).length} have a PTR record, ${s.fcrdns_ok ?? cells.filter((r) => r && r.fcrdns === true).length} are forward-confirmed and ${s.auto_generated ?? autoN} look auto-generated.`;
  drawGrid(); drawList();
  return h('div', { class: 'space-y-3' },
    h('div', { class: 'flex flex-wrap items-start gap-x-8 gap-y-3' },
      h('div', { class: 'min-w-0 w-full sm:w-auto' }, grid, tip),
      h('div', { class: 'space-y-2 text-sm' },
        h('ul', { class: 'list-none m-0 p-0 flex flex-wrap gap-x-4 gap-y-1' },
          legendKey('ptr-ok', 'PTR, forward-confirmed (best)'), legendKey('ptr-warn', 'PTR, but the name does not resolve back'), legendKey('', 'No PTR record'), legendKey('ptr-ok ptr-auto', 'Hatched: looks auto-generated')),
        autoN ? h('label', { class: 'inline-flex items-center gap-1.5 cursor-pointer' }, hideAuto, 'Hide auto-generated') : null,
        h('div', null, count),
        h('p', { class: 'text-xs text-mute max-w-[16rem]' }, `Reads left to right, top to bottom: the first square is ${base ? base.replace(/\/\d+$/, '') : '.0'}, the last is .255. Click a square to find it in the list.`))),
    srOnly(text),
    h('div', { class: 'space-y-2' }, h('h4', { class: 'font-semibold text-sm' }, 'PTR records'), search, note, body, more));
}
